  struct Pair p; int v = 5;
  p = ext_pair(7, 2.5);
  printf("x=%d,%ld,%.1f,%d,%ld,%.1f,h=%d\n",
         ext_add(20, 22), ext_long(1, 2, 3), ext_double(1.5, 4.0),
         ext_ptr(&v), p.x, p.y, hidden_add(9, 2));
  return 0;
}

